`timescale 1ns / 1ps

// ============================================================================
// tb_pipeline_memfiles.v  -  hardware_pipeline driven by memory files
//
// INPUT FILES (same folder as the simulation):
//     vertices.mem     2 triangles = 6 vertices, 144-bit words
//     matrix.mem     4x4 matrix, Q24.8, row-major (16 lines)
//     recip_lut_q1_17.mem   reciprocal LUT for the triangle setup unit
//     expected_values.vh    expected numbers (generated by expected.py)
//
// The modules load vertices.mem / matrix.mem / recip_lut_q1_17.mem themselves;
// the TB loads the same files again (from MEM_DIR) and checks they arrived, so
// a missing file stops the run with a clear ERROR instead of a black picture.
// The same 3 .mem files are used unchanged for the FPGA build.
//
// OUTPUT FILES:
//     pipeline_trace.log    per-module trace + checks (also on the console)
//     pipeline_wave.vcd     waveforms of the interesting time windows only
//     frame_capture.ppm     300x400 picture captured from the VGA outputs
//
// LOG FORMAT:  [cycle] STAGE  message
//     cycle = 100 MHz render clocks after the render reset is released
//             (cycle 0 = first clock edge the pipeline runs on, 10 ns each)
//
// Run (Icarus):  iverilog -g2012 -o sim tb_pipeline_memfiles.v <rtl files>
//                vvp sim
// Run (Vivado):  add the 4 files above as simulation sources, set this file
//                as simulation top, then "run all" (about 34 ms sim time).
//                Add the 3 .mem files to the project (design sources): Vivado
//                then copies them into <project>.sim/sim_1/behav/xsim/, where
//                the simulation runs. (It does NOT copy .hex files, which is
//                why the inputs are named .mem.) Or set MEM_DIR (below).
//                If a file is missing the TB stops at once with an ERROR line.
// ============================================================================
module tb_pipeline_memfiles #(
    // Folder that holds vertices.mem, matrix.mem and
    // recip_lut_q1_17.mem, ending in '/'. "./" = the simulator's run folder.
    // Vivado runs in <project>.sim/sim_1/behav/xsim/, so either copy the files
    // there or put your folder here (forward slashes, spaces are fine), e.g.
    //   "D:/study material 3rd sem/HLab_project/hardware_pipeline_code/"
    parameter MEM_DIR = "./"
);

    // ------------------------------------------------------------------------
    // Clocks, reset, DUT
    // ------------------------------------------------------------------------
    reg clk = 0, clk_vga = 0, rst_n = 0;
    always #5  clk     = ~clk;      // 100 MHz
    always #20 clk_vga = ~clk_vga;  //  25 MHz

    wire [3:0] vga_r, vga_g, vga_b;
    wire       vga_hs, vga_vs;

    hardware_pipeline #(
        .NUM_VERTICES   (6),
        .RECIP_LUT_FILE ({MEM_DIR, "recip_lut_q1_17.mem"})
    ) dut (
        .clk (clk), .clk_vga (clk_vga), .rst_n (rst_n),
        .vga_r (vga_r), .vga_g (vga_g), .vga_b (vga_b),
        .vga_hs (vga_hs), .vga_vs (vga_vs)
    );

    // ------------------------------------------------------------------------
    // Expected values (from expected.py)
    // ------------------------------------------------------------------------
    integer           exp_te   [0:23];  // 6 vertices x {X',Y',Z',W'}
    integer           exp_pe   [0:17];  // 6 vertices x {sx, sy, sz}
    integer           exp_bbox [0:7];   // 2 tris x {xmin, xmax, ymin, ymax}
    reg signed [63:0] exp_edge [0:17];  // 2 tris x 3 edges x {A, B, C}
    integer           exp_zc   [0:1];
    integer           exp_scan [0:1], exp_inside [0:1], exp_wr [0:1], exp_rej [0:1];
    integer           exp_fb_green, exp_fb_red;
    `include "expected_values.vh"

    // ------------------------------------------------------------------------
    // Log + helpers
    // ------------------------------------------------------------------------
    integer lg;                                     // file + console
    initial lg = $fopen("pipeline_trace.log") | 1;

    // cycle counter: updated on the FALLING edge so every posedge logger
    // below reads a stable value (no race with the DUT's posedge logic)
    integer cyc = -1;
    always @(negedge clk) if (dut.rst_n_r) cyc = cyc + 1;

    function real q8;                               // Q24.8 -> real
        input integer v;
        q8 = v / 256.0;
    endfunction

    function [8*5:1] cname;
        input [15:0] c;
        cname = (^c === 1'bx)    ? "X"     :
                (c == 16'h07E0) ? "GREEN" : (c == 16'hF800) ? "RED"   :
                (c == 16'h0000) ? "BLACK" : "OTHER";
    endfunction

    integer errors = 0, checks = 0;

    // compare one value, print only on mismatch.
    // (functions, not tasks: a function always runs to completion, so two
    //  stages logging in the same clock cycle never interleave their lines)
    function integer chk;
        input [8*24:1]    what;
        input signed [63:0] got, exp;
        begin
            chk = 0;
            checks = checks + 1;
            if (got !== exp) begin
                chk = 1;
                errors = errors + 1;
                $fdisplay(lg, "            [FAIL] %0s = %0d, expected %0d", what, got, exp);
            end
        end
    endfunction

    // compare one value, always print the result line
    task check;
        input [8*40:1] what;
        input integer  got, exp;
        begin
            checks = checks + 1;
            if (got == exp) $fdisplay(lg, "   [ ok ] %0s = %0d", what, got);
            else begin
                errors = errors + 1;
                $fdisplay(lg, "   [FAIL] %0s = %0d (expected %0d)", what, got, exp);
            end
        end
    endtask

    function integer stage_result;                  // "-> matches expected"
        input integer n_bad;
        begin
            stage_result = n_bad;
            if (n_bad == 0) $fdisplay(lg, "            -> matches expected");
        end
    endfunction

    integer bad_te, bad_pe, bad_ts, junk;           // mismatches per stage

    // ========================================================================
    // 1) VERTEX MEMORY -> TRANSFORM ENGINE  (vertex fetch FSM handshake)
    // ========================================================================
    always @(posedge clk) if (dut.rst_n_r && dut.te_valid_in && dut.te_ready_out)
        $fdisplay(lg, "[%6d] VMEM->TE   addr=%0d  X=%7.4f Y=%7.4f Z=%7.4f W=%6.3f  col=%h (%0s)",
            cyc, dut.vm_addr,
            q8($signed(dut.vm_data[143:112])), q8($signed(dut.vm_data[111:80])),
            q8($signed(dut.vm_data[79:48])),   q8($signed(dut.vm_data[47:16])),
            dut.vm_data[15:0], cname(dut.vm_data[15:0]));

    // ========================================================================
    // 2) TRANSFORM ENGINE -> PROJECTION ENGINE
    // ========================================================================
    integer n_te = 0;
    always @(posedge clk) if (dut.rst_n_r && dut.te_valid_out && dut.pe_ready_out) begin
        $fdisplay(lg, "[%6d] TE->PE     vtx%0d  X'=%7.4f Y'=%7.4f Z'=%7.4f W'=%6.3f",
            cyc, n_te,
            q8($signed(dut.te_vertex_out[143:112])), q8($signed(dut.te_vertex_out[111:80])),
            q8($signed(dut.te_vertex_out[79:48])),   q8($signed(dut.te_vertex_out[47:16])));
        if (n_te < 6) begin
            bad_te = chk("X'", $signed(dut.te_vertex_out[143:112]), exp_te[n_te*4 + 0])
                   + chk("Y'", $signed(dut.te_vertex_out[111:80]),  exp_te[n_te*4 + 1])
                   + chk("Z'", $signed(dut.te_vertex_out[79:48]),   exp_te[n_te*4 + 2])
                   + chk("W'", $signed(dut.te_vertex_out[47:16]),   exp_te[n_te*4 + 3]);
            junk = stage_result(bad_te);
        end
        n_te = n_te + 1;
    end

    // ========================================================================
    // 3) PROJECTION ENGINE -> TRIANGLE SETUP  (one triangle = 3 vertices)
    // ========================================================================
    integer n_pe = 0;
    always @(posedge clk) if (dut.rst_n_r && dut.pe_valid_out && dut.ts_in_ready) begin
        $fdisplay(lg, "[%6d] PE->TS     tri%0d %0s  screen coordinates (pixels) and depth:", cyc, n_pe, cname(dut.pe_color));
        $fdisplay(lg, "            v0 (%7.2f, %7.2f) z=%6.3f", q8(dut.pe_x0), q8(dut.pe_y0), q8(dut.pe_z0));
        $fdisplay(lg, "            v1 (%7.2f, %7.2f) z=%6.3f", q8(dut.pe_x1), q8(dut.pe_y1), q8(dut.pe_z1));
        $fdisplay(lg, "            v2 (%7.2f, %7.2f) z=%6.3f", q8(dut.pe_x2), q8(dut.pe_y2), q8(dut.pe_z2));
        if (n_pe < 2) begin
            bad_pe = chk("v0 x", dut.pe_x0, exp_pe[n_pe*9 + 0]) + chk("v0 y", dut.pe_y0, exp_pe[n_pe*9 + 1]) + chk("v0 z", dut.pe_z0, exp_pe[n_pe*9 + 2])
                   + chk("v1 x", dut.pe_x1, exp_pe[n_pe*9 + 3]) + chk("v1 y", dut.pe_y1, exp_pe[n_pe*9 + 4]) + chk("v1 z", dut.pe_z1, exp_pe[n_pe*9 + 5])
                   + chk("v2 x", dut.pe_x2, exp_pe[n_pe*9 + 6]) + chk("v2 y", dut.pe_y2, exp_pe[n_pe*9 + 7]) + chk("v2 z", dut.pe_z2, exp_pe[n_pe*9 + 8]);
            junk = stage_result(bad_pe);
        end
        n_pe = n_pe + 1;
    end

    // ========================================================================
    // 4) TRIANGLE SETUP -> RASTERIZER  (with the discard decision)
    // ========================================================================
    integer n_ts = 0, n_discard = 0, t;
    always @(posedge clk) if (dut.rst_n_r && dut.ts_out_valid && dut.ts_out_ready) begin
        $fdisplay(lg, "[%6d] TS->RAST   tri%0d %0s  bbox x[%0d..%0d] y[%0d..%0d]",
            cyc, n_ts, cname(dut.ts_color), dut.ts_xmin, dut.ts_xmax, dut.ts_ymin, dut.ts_ymax);
        $fdisplay(lg, "            edge0 A=%0d B=%0d C=%0d", dut.ts_e0A, dut.ts_e0B, dut.ts_e0C);
        $fdisplay(lg, "            edge1 A=%0d B=%0d C=%0d", dut.ts_e1A, dut.ts_e1B, dut.ts_e1C);
        $fdisplay(lg, "            edge2 A=%0d B=%0d C=%0d", dut.ts_e2A, dut.ts_e2B, dut.ts_e2C);
        $fdisplay(lg, "            depth plane zA=%0d zB=%0d zC=%0d  (z = %6.3f everywhere)",
            dut.ts_zA, dut.ts_zB, dut.ts_zC, q8(dut.ts_zC));
        $fdisplay(lg, "            flags degenerate=%0d overflow=%0d orient_neg=%0d bbox_clamped=%0d  ->  %0s",
            dut.ts_degenerate, dut.ts_overflow, dut.ts_orient_neg, dut.ts_bbox_clamped,
            dut.pipe_discard ? "DISCARD" : "SEND TO RASTERIZER");
        if (n_ts < 2) begin
            t = n_ts;
            bad_ts = chk("bbox xmin", dut.ts_xmin, exp_bbox[t*4 + 0]) + chk("bbox xmax", dut.ts_xmax, exp_bbox[t*4 + 1])
                   + chk("bbox ymin", dut.ts_ymin, exp_bbox[t*4 + 2]) + chk("bbox ymax", dut.ts_ymax, exp_bbox[t*4 + 3])
                   + chk("edge0 A", dut.ts_e0A, exp_edge[t*9 + 0]) + chk("edge0 B", dut.ts_e0B, exp_edge[t*9 + 1]) + chk("edge0 C", dut.ts_e0C, exp_edge[t*9 + 2])
                   + chk("edge1 A", dut.ts_e1A, exp_edge[t*9 + 3]) + chk("edge1 B", dut.ts_e1B, exp_edge[t*9 + 4]) + chk("edge1 C", dut.ts_e1C, exp_edge[t*9 + 5])
                   + chk("edge2 A", dut.ts_e2A, exp_edge[t*9 + 6]) + chk("edge2 B", dut.ts_e2B, exp_edge[t*9 + 7]) + chk("edge2 C", dut.ts_e2C, exp_edge[t*9 + 8])
                   + chk("zA", dut.ts_zA, 0) + chk("zB", dut.ts_zB, 0) + chk("zC", dut.ts_zC, exp_zc[t])
                   + chk("degenerate", dut.ts_degenerate, 0) + chk("overflow", dut.ts_overflow, 0)
                   + chk("orient_neg", dut.ts_orient_neg, 0);
            junk = stage_result(bad_ts);
        end
        if (dut.pipe_discard) n_discard = n_discard + 1;
        n_ts = n_ts + 1;
    end

    // ========================================================================
    // 5) RASTERIZER  (start, first pixels, last pixel, summary)
    // ========================================================================
    integer r_tri = -1, r_start = 0, r_scan = 0, r_stall = 0, r_pix = 0;
    integer scan_cnt [0:1], inside_cnt [0:1];
    reg [9:0]  last_x, last_y;
    reg [15:0] last_z;

    always @(posedge clk) if (dut.rst_n_r) begin
        if (dut.rast_tri_valid && dut.rast_idle) begin          // triangle accepted
            r_tri = r_tri + 1; r_start = cyc; r_scan = 0; r_stall = 0; r_pix = 0;
            $fdisplay(lg, "[%6d] RAST       tri%0d accepted: bbox %0d x %0d = %0d positions to scan",
                cyc, r_tri, dut.ts_xmax - dut.ts_xmin + 1, dut.ts_ymax - dut.ts_ymin + 1,
                (dut.ts_xmax - dut.ts_xmin + 1) * (dut.ts_ymax - dut.ts_ymin + 1));
        end
        if (dut.rs_dbg_state == 3'd3) begin                     // S_SCAN
            if (dut.zf_busy) begin
                if (r_stall == 0)
                    $fdisplay(lg, "[%6d] RAST       tri%0d STALLED at (x=%0d, y=%0d): z_f_buffer busy (still clearing)",
                        cyc, r_tri, dut.rs_dbg_x, dut.rs_dbg_y);
                r_stall = r_stall + 1;
            end else begin
                if (r_scan == 0 && r_stall != 0)
                    $fdisplay(lg, "[%6d] RAST       tri%0d resumed after %0d stall cycles", cyc, r_tri, r_stall);
                r_scan = r_scan + 1;
            end
        end
        if (dut.rs_pvalid && !dut.zf_busy) begin                // pixel handed over
            r_pix = r_pix + 1;
            if (r_pix <= 3)
                $fdisplay(lg, "[%6d] RAST->ZBUF tri%0d pixel #%0d (x=%0d, y=%0d) z=0x%h (%6.3f) col=%h",
                    cyc, r_tri, r_pix, dut.rs_px, dut.rs_py, dut.rs_pz, $signed(dut.rs_pz) / 16.0, dut.rs_pcolor);
            last_x = dut.rs_px; last_y = dut.rs_py; last_z = dut.rs_pz;
        end
        if (dut.rast_done) begin
            $fdisplay(lg, "[%6d] RAST->ZBUF tri%0d pixel #%0d (x=%0d, y=%0d) z=0x%h  <- last pixel",
                cyc, r_tri, r_pix, last_x, last_y, last_z);
            $fdisplay(lg, "[%6d] RAST       tri%0d done: %0d positions scanned, %0d pixels inside, %0d stall cycles",
                cyc, r_tri, r_scan, r_pix, r_stall);
            if (r_tri >= 0 && r_tri < 2) begin
                scan_cnt[r_tri] = r_scan; inside_cnt[r_tri] = r_pix;
            end
        end
    end

    // ========================================================================
    // 6) Z/F-BUFFER  (clear, and the depth decision for every pixel)
    //    a pixel in stage 2 at edge k gets its write decision (s3_we) at k+1
    // ========================================================================
    reg        zb_pend = 0;
    reg [18:0] zb_addr;
    reg signed [15:0] zb_z, zb_old;
    reg [15:0] zb_col;
    integer wr_cnt [0:1], rej_cnt [0:1], wr_shown [0:1], rej_shown [0:1];
    integer zt;
    reg zb_busy_q = 1;
    initial begin
        wr_cnt[0] = 0; wr_cnt[1] = 0; rej_cnt[0] = 0; rej_cnt[1] = 0;
        wr_shown[0] = 0; wr_shown[1] = 0; rej_shown[0] = 0; rej_shown[1] = 0;
    end

    always @(posedge clk) if (dut.rst_n_r) begin
        if (zb_busy_q && !dut.zf_busy)
            $fdisplay(lg, "[%6d] ZBUF       clear finished: %0d words written (z=0x7FFF far, colour black), clear_done=1",
                cyc, dut.u_z_f_buffer.clear_addr);
        zb_busy_q = dut.zf_busy;

        if (zb_pend) begin
            zt = (zb_col == 16'h07E0) ? 0 : 1;          // tri0 green, tri1 red
            if (dut.u_z_f_buffer.s3_we) begin
                wr_cnt[zt] = wr_cnt[zt] + 1;
                if (wr_shown[zt] < 2) begin
                    wr_shown[zt] = wr_shown[zt] + 1;
                    $fdisplay(lg, "[%6d] ZBUF       WRITE  (x=%0d, y=%0d) new z=%0d < stored z=%0d -> pixel becomes %0s",
                        cyc, zb_addr % 300, zb_addr / 300, zb_z, zb_old, cname(zb_col));
                end
            end else begin
                rej_cnt[zt] = rej_cnt[zt] + 1;
                if (rej_shown[zt] < 2) begin
                    rej_shown[zt] = rej_shown[zt] + 1;
                    $fdisplay(lg, "[%6d] ZBUF       REJECT (x=%0d, y=%0d) new z=%0d >= stored z=%0d -> %0s is hidden",
                        cyc, zb_addr % 300, zb_addr / 300, zb_z, zb_old, cname(zb_col));
                end
            end
        end
        zb_pend = dut.u_z_f_buffer.s2_valid;
        zb_addr = dut.u_z_f_buffer.s2_addr;
        zb_z    = dut.u_z_f_buffer.s2_z;
        zb_old  = dut.u_z_f_buffer.s2_old_z;
        zb_col  = dut.u_z_f_buffer.s2_color;
    end

    // ========================================================================
    // 7) VGA  (fb_ready sync, sync pulses, capture of one full frame)
    //    the outputs at a pixel clock belong to the scan position 2 clocks
    //    earlier, so a 2-deep history of (h_cnt, v_cnt) is kept
    // ========================================================================
    localparam W = 300, H = 400, NPIX = W * H;
    localparam VGA_LINE = 270;          // traced line (framebuffer y = 230)
    integer h1 = 0, v1 = 0, h2 = 0, v2 = 0, frame = 0;
    reg     hs_q = 1, vs_q = 1, rdy_q = 0, cap_on = 0, cap_done = 0;
    reg [11:0] cap [0:NPIX-1];
    reg [11:0] rgb_q = 0;
    integer hs_low = 0, vs_low = 0;

    always @(negedge clk_vga) begin
        if (dut.rst_n_v) begin
            if (!rdy_q && dut.u_vga_controller.ready_sync[1])
                $fdisplay(lg, "[%6d] VGA        fb_ready synchronised into the pixel clock domain (frame %0d, line %0d)",
                    cyc, frame, v1);
            rdy_q = dut.u_vga_controller.ready_sync[1];

            if (cap_on) begin
                if (h2 >= 170 && h2 < 470 && v2 >= 40 && v2 < 440)
                    cap[(v2 - 40) * W + (h2 - 170)] = {vga_r, vga_g, vga_b};
                if (!vga_hs) hs_low = hs_low + 1;
                if (!vga_vs) vs_low = vs_low + 1;
                // colour changes and hsync edges on the traced line
                if (v2 == VGA_LINE && {vga_r, vga_g, vga_b} != rgb_q)
                    $fdisplay(lg, "[%6d] VGA        line %0d h=%0d: RGB %h -> %h  (framebuffer x=%0d)",
                        cyc, v2, h2, rgb_q, {vga_r, vga_g, vga_b}, h2 - 170);
                if (v2 == VGA_LINE && hs_q && !vga_hs)
                    $fdisplay(lg, "[%6d] VGA        line %0d h=%0d: hsync falls", cyc, v2, h2);
                if (v2 == VGA_LINE && !hs_q && vga_hs)
                    $fdisplay(lg, "[%6d] VGA        line %0d h=%0d: hsync rises (low for %0d pixel clocks)", cyc, v2, h2, h2 - 656);
                if (vs_q && !vga_vs)
                    $fdisplay(lg, "[%6d] VGA        vsync falls at line %0d", cyc, v2);
                if (!vs_q && vga_vs)
                    $fdisplay(lg, "[%6d] VGA        vsync rises at line %0d (low for %0d lines)", cyc, v2, v2 - 490);
                if (h2 == 799 && v2 == 524) begin cap_on = 0; cap_done = 1; end
            end
            hs_q = vga_hs; vs_q = vga_vs; rgb_q = {vga_r, vga_g, vga_b};

            if (h2 == 799 && v2 == 524) begin       // last pixel of a frame
                frame = frame + 1;
                if (frame == 1 && !cap_done) begin
                    cap_on = 1;
                    $fdisplay(lg, "[%6d] VGA        frame %0d starts - capturing it from the VGA pins", cyc, frame);
                end
            end
        end
        h2 = h1; v2 = v1;
        h1 = dut.u_vga_controller.h_cnt;
        v1 = dut.u_vga_controller.v_cnt;
    end

    // colour runs per line, totals, and the picture file
    integer fb_g, fb_r, fb_k, fb_o;
    task report_frame;
        integer x, y, s, f, lit;
        reg [11:0] c;
        begin
            fb_g = 0; fb_r = 0; fb_k = 0; fb_o = 0;
            for (x = 0; x < NPIX; x = x + 1) begin
                c = cap[x];
                if      (c == 12'h0F0) fb_g = fb_g + 1;
                else if (c == 12'hF00) fb_r = fb_r + 1;
                else if (c == 12'h000) fb_k = fb_k + 1;
                else                   fb_o = fb_o + 1;
            end
            $fdisplay(lg, "\n---- VGA frame 1: colour runs on every 5th lit row (compare with expected_values.txt) ----");
            $fdisplay(lg, "     x = framebuffer column (screen h = x + 170), y = framebuffer row (screen v = y + 40)");
            for (y = 0; y < H; y = y + 5) begin
                lit = 0;
                for (x = 0; x < W; x = x + 1) if (cap[y*W + x] != 12'h000) lit = 1;
                if (lit) begin
                    $fwrite(lg, "  y=%3d :", y);
                    s = 0;
                    for (x = 1; x <= W; x = x + 1)
                        if (x == W || cap[y*W + x] != cap[y*W + s]) begin
                            if (cap[y*W + s] == 12'h0F0) $fwrite(lg, "  GREEN x[%0d..%0d]", s, x - 1);
                            if (cap[y*W + s] == 12'hF00) $fwrite(lg, "  RED x[%0d..%0d]",   s, x - 1);
                            s = x;
                        end
                    $fdisplay(lg, "");
                end
            end
            f = $fopen("frame_capture.ppm", "w");
            $fwrite(f, "P3\n%0d %0d\n15\n", W, H);
            for (x = 0; x < NPIX; x = x + 1)
                $fwrite(f, "%0d %0d %0d\n", cap[x][11:8], cap[x][7:4], cap[x][3:0]);
            $fclose(f);
            $fdisplay(lg, "  picture written to frame_capture.ppm");
        end
    endtask

    // ========================================================================
    // MAIN SEQUENCE
    // ========================================================================
    integer k, quiet;

    initial begin
        // ---- waveform: top-level nets of the DUT + a few internals ----
        $dumpfile("pipeline_wave.vcd");
        $dumpvars(1, dut);
        $dumpvars(0, dut.u_projection_engine.vertex_count);
        $dumpvars(0, dut.u_rasterizer.state, dut.u_rasterizer.x_cur, dut.u_rasterizer.y_cur);
        $dumpvars(0, dut.u_z_f_buffer.state, dut.u_z_f_buffer.clear_addr,
                     dut.u_z_f_buffer.s1_valid, dut.u_z_f_buffer.s1_addr,
                     dut.u_z_f_buffer.s2_valid, dut.u_z_f_buffer.s2_addr,
                     dut.u_z_f_buffer.s2_z, dut.u_z_f_buffer.s2_old_z,
                     dut.u_z_f_buffer.s3_we, dut.u_z_f_buffer.s3_addr, dut.u_z_f_buffer.s3_z);
        $dumpvars(0, dut.u_vga_controller.h_cnt, dut.u_vga_controller.v_cnt,
                     dut.u_vga_controller.ready_sync);

        // ---- load the memory files while reset is held ----
        #1;
        $readmemh({MEM_DIR, "vertices.mem"},   dut.u_vertex_memory.ram, 0, 5);
        $readmemh({MEM_DIR, "matrix.mem"},   dut.u_matrix_memory.matrix_regs);
        $readmemh({MEM_DIR, "recip_lut_q1_17.mem"}, dut.u_triangle_setup.recip_rom);
        #1;     // let the matrix wires settle before printing them

        // ---- stop at once if a file was not found (memory still unknown) ----
        if (^dut.u_vertex_memory.ram[5]          === 1'bx) begin
            $fdisplay(lg, "ERROR: could not load %0s - file not found or too short", {MEM_DIR, "vertices.mem"});
            errors = errors + 1;
        end
        if (^dut.u_matrix_memory.matrix_regs[15] === 1'bx) begin
            $fdisplay(lg, "ERROR: could not load %0s - file not found or too short", {MEM_DIR, "matrix.mem"});
            errors = errors + 1;
        end
        if (^dut.u_triangle_setup.recip_rom[1023] === 1'bx) begin
            $fdisplay(lg, "ERROR: could not load %0s - file not found or too short", {MEM_DIR, "recip_lut_q1_17.mem"});
            errors = errors + 1;
        end
        if (errors != 0) begin
            $fdisplay(lg, "       The simulator looks for files relative to its run folder");
            $fdisplay(lg, "       (Vivado: <project>.sim/sim_1/behav/xsim/). Copy the files there,");
            $fdisplay(lg, "       or set the MEM_DIR parameter at the top of this testbench.");
            $fdisplay(lg, " TEST FAILED (memory files missing - nothing would be drawn)");
            $finish;
            forever #1000;      // never continue, even if the simulator is resumed
        end

        $fdisplay(lg, "==========================================================================");
        $fdisplay(lg, " hardware_pipeline trace - scene from vertices.mem / matrix.mem");
        $fdisplay(lg, " [cycle] = 100 MHz render clocks after the render reset is released (10 ns)");
        $fdisplay(lg, "==========================================================================");
        $fdisplay(lg, "\n---- MATRIX as seen by transform_engine (M00..M33) ----");
        $fdisplay(lg, "   | %6.3f %6.3f %6.3f %6.3f |", q8(dut.u_transform_engine.M00), q8(dut.u_transform_engine.M01), q8(dut.u_transform_engine.M02), q8(dut.u_transform_engine.M03));
        $fdisplay(lg, "   | %6.3f %6.3f %6.3f %6.3f |", q8(dut.u_transform_engine.M10), q8(dut.u_transform_engine.M11), q8(dut.u_transform_engine.M12), q8(dut.u_transform_engine.M13));
        $fdisplay(lg, "   | %6.3f %6.3f %6.3f %6.3f |", q8(dut.u_transform_engine.M20), q8(dut.u_transform_engine.M21), q8(dut.u_transform_engine.M22), q8(dut.u_transform_engine.M23));
        $fdisplay(lg, "   | %6.3f %6.3f %6.3f %6.3f |", q8(dut.u_transform_engine.M30), q8(dut.u_transform_engine.M31), q8(dut.u_transform_engine.M32), q8(dut.u_transform_engine.M33));
        $fdisplay(lg, "\n---- VERTEX MEMORY contents (raw 144-bit words) ----");
        for (k = 0; k < 6; k = k + 1)
            $fdisplay(lg, "   [%0d] %h", k, dut.u_vertex_memory.ram[k]);

        // ---- reset ----
        repeat (20) @(posedge clk);
        @(negedge clk) rst_n = 1;
        wait (dut.rst_n_r);
        $fdisplay(lg, "\n---- PIPELINE TRACE ----");
        $fdisplay(lg, "         RESET      rst_n released at t=%0d ns; render reset leaves the 2-FF synchroniser", $time);
        $fdisplay(lg, "[%6d] ZBUF       clear started: 120000 words, 1 per clock (1.2 ms); rasterizer is held while busy", 0);

        // keep the first 60 cycles (fetch .. setup) in the VCD, then pause it
        repeat (60) @(posedge clk);
        $dumpoff;

        // resume the VCD just before the clear ends, keep it for the render
        wait (dut.u_z_f_buffer.clear_addr >= 119980);
        $dumpon;
        wait (dut.zf_clear_done);

        // render done = fetch FSM finished and every stage idle for 50 clocks
        quiet = 0;
        while (quiet < 50) begin
            @(posedge clk);
            if (dut.f_state == 2'd2 && !dut.te_valid_out && !dut.pe_valid_out &&
                !dut.ts_out_valid && dut.rast_idle && !dut.rs_pvalid && !dut.u_z_f_buffer.s3_we)
                quiet = quiet + 1;
            else
                quiet = 0;
        end
        $dumpoff;

        $fdisplay(lg, "\n---- RENDER SUMMARY (cycle %0d, t=%0d ns) ----", cyc, $time);
        check("vertices through transform engine", n_te, 6);
        check("triangles out of projection engine", n_pe, 2);
        check("triangles out of setup unit",        n_ts, 2);
        check("triangles discarded",                n_discard, 0);
        check("tri0 GREEN positions scanned",       scan_cnt[0],   exp_scan[0]);
        check("tri0 GREEN pixels inside",           inside_cnt[0], exp_inside[0]);
        check("tri1 RED   positions scanned",       scan_cnt[1],   exp_scan[1]);
        check("tri1 RED   pixels inside",           inside_cnt[1], exp_inside[1]);
        check("z-buffer GREEN written",             wr_cnt[0],  exp_wr[0]);
        check("z-buffer GREEN rejected",            rej_cnt[0], exp_rej[0]);
        check("z-buffer RED written",               wr_cnt[1],  exp_wr[1]);
        check("z-buffer RED rejected",              rej_cnt[1], exp_rej[1]);
        $fdisplay(lg, "");

        // ---- one VGA line (colour edges + hsync) into the VCD ----
        wait (frame == 1 && dut.u_vga_controller.v_cnt == VGA_LINE && dut.u_vga_controller.h_cnt == 300);
        $dumpon;
        wait (dut.u_vga_controller.v_cnt == VGA_LINE + 1);
        $dumpoff;

        // ---- wait for the captured frame and check it ----
        wait (cap_done);
        report_frame;
        $fdisplay(lg, "\n---- VGA SUMMARY ----");
        check("VGA GREEN pixels (RGB444 0F0)", fb_g, exp_fb_green);
        check("VGA RED pixels   (RGB444 F00)", fb_r, exp_fb_red);
        check("VGA other colours",             fb_o, 0);
        check("hsync low clocks per frame",    hs_low, 96 * 525);
        check("vsync low clocks per frame",    vs_low, 2 * 800);

        $fdisplay(lg, "\n==========================================================================");
        if (errors == 0) $fdisplay(lg, " TEST PASSED  (%0d checks)", checks);
        else             $fdisplay(lg, " TEST FAILED  (%0d of %0d checks failed)", errors, checks);
        $fdisplay(lg, "==========================================================================");
        $fclose(lg & ~1);
        $finish;
    end

    initial begin
        #40_000_000;
        $fdisplay(lg, "[FAIL] watchdog: simulation took too long");
        $finish;
    end

endmodule
